const customer = $('Get many Customers5').first().json.display_name;
const setItems = $input.all();
const parserProducts = $('AI Agent - Create Sales Order4').first().json.output.products || [];

let list = setItems.map(it => {
  const displayName = it.json.display_name || "";

  // Find matching product in AI Agent output
  const match = parserProducts.find(p => {
    const name = (p.product_name || "").toLowerCase();
    return displayName.toLowerCase().includes(name) || name.includes(displayName.toLowerCase());
  });

  const qty = match ? match.quantity : 0;
  return `${displayName} (x${qty})`;
}).join(", ");

return {
  reply: `Sales order created successfully for ${customer} with ${list}.`
};

options.systemMessage:
You are an Odoo sales assistant.

Your job is to extract all relevant information from the user's message to create a sales order. 

Always respond **ONLY in structured JSON** (no explanations, markdown, or extra text) in the following format:

{
  "customer_name": "string",          // Name of the customer
  "products": [                        // List of products in the order
    {
      "product_name": "string",       // Name of the product exactly as mentioned
      "quantity": number              // Quantity of that product
    }
  ]
}

Rules:
1. Extract **all products** mentioned in the message, even if there are multiple.
2. If a product is mentioned without a quantity, set quantity to null.
3. If the customer name is missing, set customer_name to null.
4. Always return valid JSON. Never return text outside JSON.
5. Use the product names **exactly as in the user's message** for now; matching with Odoo products will happen later.

Example user message:
"Create a sales order for Mohammed Ali with product 'Acoustic Bloc Screens' in quantity 10 and product 'Office Chair' in quantity 5."

Expected JSON output:
{
  "customer_name": "Mohammed Ali",
  "products": [
    {"product_name": "Acoustic Bloc Screens", "quantity": 10},
    {"product_name": "Office Chair", "quantity": 5}
  ]
}

